#!/usr/bin/env python3
# GENERATED by PrototypeFramework 0.9.0 from Documentation~/agent/tools/pixel-probe.py — do not edit here. Change it in the framework repo, then run Framework/Agent Docs/Sync (editor) or Tools/Build/pf-build.sh agentdocs.
# pixel-probe.py — settle a capture's *floor* deterministically, with no model in the loop.
#
# `visual-judge.sh` asks a vision model "does this look right?" — the ceiling, and the right
# question for a `kind: finish` story. This asks the floor question a `kind: function` story
# actually needs: "is this wired up at all?" — did anything render, is it the right material,
# the right colour space, is the renderer enabled, is it on top of what it should be on top of.
# Every one of those failures moves a *known pixel* to a *known wrong colour*, so every one of
# them is settled by reading that pixel and comparing it to the design token it was drawn from.
# No LLM, no quota, no non-determinism: this runs inside `dotnet test` and answers the same way
# every time.
#
# It never judges composition, balance, polish or "does it look good" — those are the ceiling's
# and they belong to `visual-judge.sh` against an approved reference.
#
# Usage:
#   Tools/pf/pixel-probe.py --capture <png> --points <points.json> [--mask <mask.png>]
#                               [--coverage <coverage.json>] [--min-variance <f>] [--window <n>]
#                               [--verbose]
#   Tools/pf/pixel-probe.py --variance-only <png> [--min-variance <f>]
#   Tools/pf/pixel-probe.py --generate <layout.json> [--out <points.json>]
#
#   --capture        the PNG to read
#   --points         the sample-point declaration (schema `pixel-probe/v1` or `/v2`, see below)
#   --variance-only  print the capture's luma variance and settle ONLY the broken-capture check
#                    (this is the mode `visual-judge.sh` shells out to)
#   --min-variance   override the flat-capture threshold (default: the points file, else 4.0)
#   --window         override every probe's sample-box size (odd, in design units)
#   --generate       machine-generate a points file from a higher-level layout declaration
#                    (schema `pixel-probe-layout/v1` or `/v2`) — anchored rects x design tokens, so
#                    no coordinate and no hex value is ever hand-typed into the points file
#   --out            where --generate writes (default: stdout)
#   --mask           the coverage floor's 24-bit RGB label mask (default: <capture stem>.mask.png
#                    beside the capture); read only when a v2 file declares an art-probed drawable
#   --coverage       the coverage sidecar, every number the capture harness MEASURED (default:
#                    <capture stem>.coverage.json beside the capture); read when a v2 file declares
#                    any drawable
#
# Coverage (schema `pixel-probe-layout/v2` -> `pixel-probe/v2`)
#   A v2 file also carries the capture's DRAWABLE INVENTORY — every Renderer and uGUI Graphic that
#   renders into the frame, minus what draws nothing by design — and the floor requires each one to
#   be covered by AT LEAST ONE of (an exemption wins over everything else):
#     * an ART PROBE (kind `art`, automatic): on the drawable's colour-measurable pixels (mask label
#       n — visible pixels no other drawable also changes, where its own texel x tint has alpha) the
#       median CIELAB of the capture is within `art.tolerance` dE76 (default 4.0) of the median the
#       harness derived from the drawable's own texture x tint composited over the frame without it.
#       The C# side measured that expectation from data — texels decoded from the texture's SOURCE
#       PNG/JPG, so the expectation never shares the import path with the render (`texelSource:
#       "import"` in the sidecar says it had to, and the art line says so); this tool only compares. It
#       catches RENDER-PATH faults: a colour-space slip (including a texture imported with the wrong sRGB
#       flag), shader or blend behaviour, occlusion, a missing sprite. It never catches a wrong tint or
#       colour VALUE — the expectation is built from that same value; that stays a field assertion
#       against the design token.
#     * a PRESENCE PROBE (kind `text`, automatic): at least `art.minPixels` (16) pixels change when the
#       label is removed. No colour expectation — text colour stays a field assertion and the judge's.
#     * an ATTRIBUTED POINT PROBE that lands on it: a point whose `target` names the drawable and whose
#       centre is on one of the drawable's visible pixels (else FAIL "probe misses its target"), or —
#       with no target — the smallest non-exempt drawable among those the sidecar says are visible at
#       the probe's centre (`hits`). The generator's `target` for such a probe is only its structural
#       guess (smallest non-exempt bounds holding the centre); the settle credits what was really there.
#     * an EXEMPTION with a non-blank reason (a blank one is exit 2, naming the drawable).
#   DRIFT (exit 1): an uncovered drawable; one that NEVER REACHES THE FRAME (0 visible pixels — or,
#   for text, fewer than 16); an art drawable that is visible but COLOUR-UNMEASURABLE (fewer than 16
#   colour-measurable pixels: under a translucent dim, overlapped by a soft shadow) and has no point
#   probe; a targeted point probe that misses its target. ERROR (exit 2): an art drawable whose
#   unshared visible pixels do not map onto its own quad (`mapped` < 16 <= `unshared`) — that is a
#   harness mapping defect, never an overlay, and exempting it would hide a bug. Two colour-purpose
#   point probes reading the
#   same token (or hex, with no token) on the same render path prove the same thing twice: that is a
#   WARN and never changes the exit code. Keep one colour probe and tag the rest `purpose: presence`,
#   which silences the lint and nothing else: a presence-tagged probe still reads and checks its
#   colour. An exemption that matched
#   no drawable is a WARN too. A v1 points file is settled exactly as before and says that coverage
#   was not declared.
#
# Exit-code contract (CliConventions.ExitCode): 0 Ok · 1 Drift · 2 Error.
#   0 = every probe within tolerance and every drawable covered (or, in --variance-only, the capture
#       is not flat)
#   1 = at least one probe outside tolerance, or a drawable uncovered / never reaching the frame /
#       colour-unmeasurable, or a probe missing its target (or, in --variance-only, the capture IS
#       flat)
#   2 = could not run (no capture, no points file, undecodable PNG, malformed declaration, a missing
#       or mismatched mask / coverage sidecar, an exemption with a blank reason, an art drawable the
#       harness could not map onto its own pixels, or any unexpected fault — never read as Drift)
#
# The flat-capture check runs FIRST and outranks every probe. A capture that is very nearly one
# flat colour is a BROKEN CAPTURE, not a wrong colour: every probe would "fail" and every one of
# those failures would name the wrong cause. Reported as exit 2, never as exit 1. This is not
# hypothetical here — see `Tools/UiGate/judge-calibration.md`: the Game View's render texture has
# been observed reading back a uniform `RGBA(0.098, 0.098, 0.122, 1)` across the entire frame.
#
# Why ΔE76 (CIE76) and not an RGB distance
#   sRGB distance is not perceptually even: 20 units apart is glaring in a dark navy like
#   `ShelfRecess` and invisible in a cream like `Ground`, so one repo-wide RGB tolerance is either
#   too tight on the lights or too loose on the darks. ΔE76 is computed in CIELAB, which is
#   roughly perceptually uniform, so ONE number means the same thing on every token: ~1 is the
#   just-noticeable difference, ~2-3 is "a careful eye sees it", >10 is "those are different
#   colours". It also has the property this gate needs most — a colour-space mistake (a linear
#   value written where an sRGB one was meant, or the reverse) shifts midtone LIGHTNESS hard, and
#   L* is exactly what ΔE76 is most sensitive to. CIE76 rather than CIEDE2000 on purpose: the
#   later formulas buy accuracy in saturated hue differences this gate does not need, at the cost
#   of a page of magic constants nobody in review can check by hand.
#
# Decoder: Pillow when importable (fast path), otherwise a stdlib-only PNG reader (zlib +
# struct — 8/16-bit, colour types 0/2/3/4/6, non-interlaced). numpy is NOT required and is NOT
# present on this rig. Both paths produce identical numbers: variance is always measured on the
# same integer luma over the same deterministic subsample, so a variance reading is comparable
# across runs and across machines (which is what `visual-judge.sh`'s HALT rule leans on).

import argparse
import ast
import json
import os
import re
import struct
import sys
import zlib

TOOL = "pixel-probe"

EXIT_OK = 0
EXIT_DRIFT = 1
EXIT_ERROR = 2

DEFAULT_MIN_VARIANCE = 4.0
DEFAULT_TOLERANCE = 10.0
DEFAULT_WINDOW = 5
DEFAULT_SPACE = (1080, 1920)
DEFAULT_ART_TOLERANCE = 4.0
DEFAULT_MIN_PIXELS = 16

LAYOUT_V2 = "pixel-probe-layout/v2"
POINTS_V2 = "pixel-probe/v2"
COVERAGE_V1 = "pixel-probe-coverage/v1"
KINDS = ("art", "text", "other")
TEXEL_SOURCES = ("asset", "import", "solid")

# Cap on how many pixels the variance reading looks at. A flat frame is flat everywhere, so a
# deterministic stride is as good as the full frame and keeps the stdlib decoder path usable.
VARIANCE_SAMPLE_CAP = 262144


class ProbeError(Exception):
    """Anything that makes the run impossible — always exit 2, never exit 1."""


def warn(msg):
    sys.stderr.write("[%s] %s\n" % (TOOL, msg))


# --- image loading ----------------------------------------------------------------------------


class Raster(object):
    """A decoded image as one flat RGB byte buffer. Deliberately decoder-agnostic."""

    __slots__ = ("width", "height", "data")

    def __init__(self, width, height, data):
        self.width = width
        self.height = height
        self.data = data

    def rgb(self, x, y):
        i = (y * self.width + x) * 3
        return self.data[i], self.data[i + 1], self.data[i + 2]


def _load_with_pillow(path):
    try:
        from PIL import Image
    except ImportError:
        return None
    try:
        with Image.open(path) as im:
            rgb = im.convert("RGB")
            return Raster(rgb.width, rgb.height, bytearray(rgb.tobytes()))
    except Exception as exc:  # a corrupt file is an error, not a verdict
        raise ProbeError("Pillow could not decode %s: %s" % (path, exc))


_PNG_CHANNELS = {0: 1, 2: 3, 3: 1, 4: 2, 6: 4}


def _paeth(a, b, c):
    p = a + b - c
    pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
    if pa <= pb and pa <= pc:
        return a
    if pb <= pc:
        return b
    return c


def _load_with_stdlib(path):
    """Minimal PNG reader: enough for anything Unity writes, nothing more."""
    with open(path, "rb") as fh:
        blob = fh.read()
    if blob[:8] != b"\x89PNG\r\n\x1a\n":
        raise ProbeError("not a PNG file: %s" % path)

    pos = 8
    header = None
    palette = None
    idat = []
    while pos + 8 <= len(blob):
        (length,) = struct.unpack(">I", blob[pos:pos + 4])
        kind = blob[pos + 4:pos + 8]
        body = blob[pos + 8:pos + 8 + length]
        pos += 12 + length
        if kind == b"IHDR":
            header = struct.unpack(">IIBBBBB", body)
        elif kind == b"PLTE":
            palette = body
        elif kind == b"IDAT":
            idat.append(body)
        elif kind == b"IEND":
            break
    if header is None:
        raise ProbeError("PNG has no IHDR chunk: %s" % path)

    width, height, depth, colour, compression, filt, interlace = header
    if interlace:
        raise ProbeError(
            "interlaced PNG needs Pillow to decode (%s); `pip install Pillow`" % path)
    if compression != 0 or filt != 0:
        raise ProbeError("unsupported PNG compression/filter in %s" % path)
    if depth not in (8, 16) or colour not in _PNG_CHANNELS:
        raise ProbeError("unsupported PNG bit depth %d / colour type %d in %s"
                         % (depth, colour, path))
    if colour == 3 and palette is None:
        raise ProbeError("palette PNG with no PLTE chunk: %s" % path)

    channels = _PNG_CHANNELS[colour]
    step = channels * (depth // 8)
    stride = width * step
    raw = zlib.decompress(b"".join(idat))
    if len(raw) < (stride + 1) * height:
        raise ProbeError("truncated PNG image data: %s" % path)

    # Un-filter, scanline by scanline, in place.
    lines = []
    prev = bytearray(stride)
    at = 0
    for _ in range(height):
        ftype = raw[at]
        line = bytearray(raw[at + 1:at + 1 + stride])
        at += 1 + stride
        if ftype == 1:
            for i in range(step, stride):
                line[i] = (line[i] + line[i - step]) & 0xFF
        elif ftype == 2:
            for i in range(stride):
                line[i] = (line[i] + prev[i]) & 0xFF
        elif ftype == 3:
            for i in range(stride):
                left = line[i - step] if i >= step else 0
                line[i] = (line[i] + ((left + prev[i]) >> 1)) & 0xFF
        elif ftype == 4:
            for i in range(stride):
                left = line[i - step] if i >= step else 0
                upleft = prev[i - step] if i >= step else 0
                line[i] = (line[i] + _paeth(left, prev[i], upleft)) & 0xFF
        elif ftype != 0:
            raise ProbeError("unknown PNG filter type %d in %s" % (ftype, path))
        lines.append(line)
        prev = line

    # Flatten to RGB. 16-bit keeps the high byte; alpha is dropped (captures are opaque).
    hi = 1 if depth == 16 else 0
    out = bytearray(width * height * 3)
    o = 0
    for line in lines:
        for x in range(width):
            base = x * step
            if colour == 3:
                idx = line[base] * 3
                out[o] = palette[idx]
                out[o + 1] = palette[idx + 1]
                out[o + 2] = palette[idx + 2]
            elif colour in (0, 4):
                g = line[base + hi]
                out[o] = out[o + 1] = out[o + 2] = g
            else:
                out[o] = line[base + hi]
                out[o + 1] = line[base + (depth // 8) + hi]
                out[o + 2] = line[base + 2 * (depth // 8) + hi]
            o += 3
    return Raster(width, height, out)


def load_raster(path):
    if not os.path.isfile(path):
        raise ProbeError("capture not found: %s" % path)
    raster = _load_with_pillow(path)
    if raster is None:
        raster = _load_with_stdlib(path)
    if raster.width == 0 or raster.height == 0:
        raise ProbeError("capture has zero extent: %s" % path)
    return raster


# --- colour -----------------------------------------------------------------------------------


def parse_hex(text):
    s = str(text).strip().lstrip("#")
    if len(s) == 3:
        s = "".join(c * 2 for c in s)
    if len(s) == 8:  # #RRGGBBAA — alpha is not a thing a probe can read back
        s = s[:6]
    if len(s) != 6 or re.search(r"[^0-9a-fA-F]", s):
        raise ProbeError("not a hex colour: %r" % (text,))
    return int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16)


def hex_of(rgb):
    return "#%02X%02X%02X" % (int(round(rgb[0])), int(round(rgb[1])), int(round(rgb[2])))


def _srgb_to_linear(c):
    c = c / 255.0
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


_D65 = (0.95047, 1.00000, 1.08883)


def linear_to_lab(r, g, b):
    """Linear-light sRGB -> CIELAB (D65). Linear in, because a sampled patch is averaged in
    linear light — averaging gamma-encoded bytes biases a gradient towards its dark end."""
    x = 0.4124564 * r + 0.3575761 * g + 0.1804375 * b
    y = 0.2126729 * r + 0.7151522 * g + 0.0721750 * b
    z = 0.0193339 * r + 0.1191920 * g + 0.9503041 * b

    def f(t):
        t = t if t > 0.0 else 0.0
        return t ** (1.0 / 3.0) if t > 216.0 / 24389.0 else (841.0 / 108.0) * t + 4.0 / 29.0

    fx, fy, fz = f(x / _D65[0]), f(y / _D65[1]), f(z / _D65[2])
    return 116.0 * fy - 16.0, 500.0 * (fx - fy), 200.0 * (fy - fz)


def srgb_bytes_to_lab(rgb):
    return linear_to_lab(*[_srgb_to_linear(c) for c in rgb])


def delta_e76(lab_a, lab_b):
    return ((lab_a[0] - lab_b[0]) ** 2
            + (lab_a[1] - lab_b[1]) ** 2
            + (lab_a[2] - lab_b[2]) ** 2) ** 0.5


# --- the flat-capture check -------------------------------------------------------------------


def luma_variance(raster):
    """Population variance of integer Rec.601 luma over a deterministic subsample.

    Same algorithm on both decoder paths on purpose: `visual-judge.sh`'s HALT rule compares one
    run's reading against the previous run's, so the number has to mean the same thing twice."""
    total = raster.width * raster.height
    stride = 1
    while total // stride > VARIANCE_SAMPLE_CAP:
        stride += 1
    data = raster.data
    n = 0
    acc = 0
    acc_sq = 0
    for i in range(0, total, stride):
        j = i * 3
        y = (299 * data[j] + 587 * data[j + 1] + 114 * data[j + 2]) // 1000
        acc += y
        acc_sq += y * y
        n += 1
    if n == 0:
        raise ProbeError("no pixels sampled")
    mean = acc / float(n)
    return max(0.0, acc_sq / float(n) - mean * mean), n, stride


def check_variance(raster, path, minimum):
    variance, sampled, stride = luma_variance(raster)
    flat = variance < minimum
    if flat:
        warn("BROKEN CAPTURE: %s is very nearly one flat colour "
             "(luma variance %.4f < %.4f, %d px sampled at stride %d)."
             % (path, variance, minimum, sampled, stride))
        warn("This is a capture-pipeline fault, not a UI fault — nothing was drawn into the "
             "frame. Do not read any verdict below it.")
    return variance, flat


# --- points file ------------------------------------------------------------------------------


_ANCHORS = {
    "center": (0.5, 0.5),
    "top-left": (0.0, 0.0),
    "top-center": (0.5, 0.0),
    "top-right": (1.0, 0.0),
    "left-center": (0.0, 0.5),
    "right-center": (1.0, 0.5),
    "bottom-left": (0.0, 1.0),
    "bottom-center": (0.5, 1.0),
    "bottom-right": (1.0, 1.0),
}


def read_json(path, what):
    if not os.path.isfile(path):
        raise ProbeError("%s not found: %s" % (what, path))
    try:
        with open(path, "r") as fh:
            return json.load(fh)
    except ValueError as exc:
        raise ProbeError("%s is not valid JSON (%s): %s" % (what, exc, path))


def sample_patch(raster, cx, cy, window):
    """Mean colour of a window x window box, averaged in LINEAR light, clamped to the frame."""
    half = max(0, window // 2)
    x0, x1 = max(0, cx - half), min(raster.width - 1, cx + half)
    y0, y1 = max(0, cy - half), min(raster.height - 1, cy + half)
    lin = [0.0, 0.0, 0.0]
    srgb = [0, 0, 0]
    n = 0
    for y in range(y0, y1 + 1):
        for x in range(x0, x1 + 1):
            px = raster.rgb(x, y)
            for c in range(3):
                lin[c] += _srgb_to_linear(px[c])
                srgb[c] += px[c]
            n += 1
    lin = [v / n for v in lin]
    srgb = [v / float(n) for v in srgb]
    return lin, srgb


def run_probes(raster, spec, capture_path, window_override, verbose):
    space = spec.get("space") or {}
    design_w = int(space.get("width", DEFAULT_SPACE[0]))
    design_h = int(space.get("height", DEFAULT_SPACE[1]))
    origin = space.get("origin", "top-left")
    if origin not in ("top-left", "bottom-left"):
        raise ProbeError("space.origin must be 'top-left' or 'bottom-left', got %r" % origin)
    if design_w <= 0 or design_h <= 0:
        raise ProbeError("space.width/height must be positive")

    defaults = spec.get("defaults") or {}
    def_tol = float(defaults.get("tolerance", DEFAULT_TOLERANCE))
    def_win = int(defaults.get("window", DEFAULT_WINDOW))

    points = spec.get("points")
    if not isinstance(points, list) or (not points and not is_v2(spec)):
        raise ProbeError("points file declares no `points` array")

    sx = raster.width / float(design_w)
    sy = raster.height / float(design_h)
    if verbose:
        warn("design space %dx%d (%s origin) -> capture %dx%d, scale %.4f x %.4f"
             % (design_w, design_h, origin, raster.width, raster.height, sx, sy))

    failures = 0
    for index, point in enumerate(points):
        label = point.get("label") or "point %d" % (index + 1)
        try:
            dx = float(point["x"])
            dy = float(point["y"])
            expect = parse_hex(point["expect"])
        except KeyError as exc:
            raise ProbeError("point %r is missing %s" % (label, exc))
        tol = float(point.get("tolerance", def_tol))
        win = int(window_override if window_override else point.get("window", def_win))

        if origin == "bottom-left":
            dy = design_h - 1 - dy
        px = int(round(dx * sx))
        py = int(round(dy * sy))
        if not (0 <= px < raster.width and 0 <= py < raster.height):
            print("FAIL | %-52s | (%d,%d) falls outside the %dx%d capture"
                  % (label, px, py, raster.width, raster.height))
            failures += 1
            continue

        lin, srgb = sample_patch(raster, px, py, win)
        got_lab = linear_to_lab(*lin)
        want_lab = srgb_bytes_to_lab(expect)
        de = delta_e76(got_lab, want_lab)
        rgb_gap = max(abs(srgb[c] - expect[c]) for c in range(3))
        ok = de <= tol
        failures += 0 if ok else 1
        token = point.get("token")
        print("%s | %-52s | got %s want %s%s | dE76 %6.2f (tol %5.2f) | max RGB gap %5.1f | @(%d,%d) %dpx box"
              % ("PASS" if ok else "FAIL",
                 label,
                 hex_of(srgb),
                 hex_of(expect),
                 (" [%s]" % token) if token else "",
                 de, tol, rgb_gap, px, py, win))
        if verbose and point.get("from"):
            warn("    %s: %s" % (label, point["from"]))

    if is_v2(spec):
        return failures
    print("[%s] %s capture=%s points=%d failed=%d"
          % (TOOL, "DRIFT" if failures else "Ok", capture_path, len(points), failures))
    print("[%s] NOTICE coverage was not declared (a v1 points file): only the %d point probe(s) "
          "above were settled — no drawable inventory was checked, so a drawable nobody pointed a "
          "probe at was not looked at. Re-emit through the capture harness for a v2 file."
          % (TOOL, len(points)))
    return EXIT_DRIFT if failures else EXIT_OK


# --- the coverage floor (v2) ------------------------------------------------------------------


def is_v2(spec):
    return spec.get("$schema") in (POINTS_V2, LAYOUT_V2) or "drawables" in spec


def _array(doc, key, what):
    value = doc.get(key)
    if value is None:
        return []
    if not isinstance(value, list):
        raise ProbeError("%s: `%s` must be an array" % (what, key))
    return value


def _count(value, what):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ProbeError("%s must be a non-negative integer, got %r" % (what, value))
    return value


def coverage_blocks(doc, what):
    """The v2 structure, validated: drawables, exemptions, ids and the reason each exempt id carries.
    Shared by --generate (layout) and --capture (points)."""
    drawables = _array(doc, "drawables", what)
    exemptions = _array(doc, "exemptions", what)
    ids = {}
    for d in drawables:
        if not isinstance(d, dict):
            raise ProbeError("%s: a drawable entry is not an object: %r" % (what, d))
        did = d.get("id")
        if not did or not isinstance(did, str):
            raise ProbeError("%s: a drawable has no `id`" % what)
        if did in ids:
            raise ProbeError("%s: drawable id %r is declared twice" % (what, did))
        bounds = d.get("bounds")
        if not isinstance(bounds, list) or len(bounds) != 4 \
                or any(isinstance(v, bool) or not isinstance(v, int) for v in bounds):
            raise ProbeError("%s: drawable %r has no integer [x, y, w, h] `bounds`" % (what, did))
        if d.get("kind") not in KINDS:
            raise ProbeError("%s: drawable %r has kind %r (%s)" % (what, did, d.get("kind"), " | ".join(KINDS)))
        ids[did] = d
    exempt = {}
    for e in exemptions:
        if not isinstance(e, dict):
            raise ProbeError("%s: an exemption entry is not an object: %r" % (what, e))
        covered = e.get("drawables")
        if not isinstance(covered, list):
            raise ProbeError("%s: the exemption of %r has no `drawables` array" % (what, e.get("path")))
        if not str(e.get("reason") or "").strip():
            named = ", ".join("%s [%s]" % (c, ids[c].get("renderPath", "?")) if c in ids else str(c)
                              for c in covered) or "no drawable"
            raise ProbeError("%s: the %s exemption of %r carries a blank reason (it covers %s) — every "
                             "exemption states why the drawable cannot be probed"
                             % (what, e.get("scope", "drawable"), e.get("path"), named))
        for did in covered:
            if did not in ids:
                raise ProbeError("%s: the exemption of %r names unknown drawable %r"
                                 % (what, e.get("path"), did))
            exempt.setdefault(did, str(e["reason"]).strip())
    return drawables, exemptions, ids, exempt


def attribute(x, y, drawables, exempt=None, among=None):
    """The smallest-area drawable whose pixel bounds contain (x, y); first declared wins a tie. An
    exempt drawable is never credited, and with `among` only the drawables named in it count (the
    settle passes the ids the sidecar says are visible at the centre)."""
    best, best_area = None, None
    for d in drawables:
        if exempt and d["id"] in exempt:
            continue
        if among is not None and d["id"] not in among:
            continue
        bx, by, bw, bh = d["bounds"]
        if bx <= x < bx + bw and by <= y < by + bh:
            area = bw * bh
            if best is None or area < best_area:
                best, best_area = d, area
    return best


def default_sidecar(capture_path, suffix):
    stem, _ = os.path.splitext(capture_path)
    return stem + suffix


def default_mask_path(capture_path):
    return default_sidecar(capture_path, ".mask.png")


def _median(values):
    values = sorted(values)
    mid = len(values) // 2
    return values[mid] if len(values) % 2 else (values[mid - 1] + values[mid]) * 0.5


def load_coverage(path, ids, points, spec, raster):
    """The sidecar the capture harness measured beside the capture, checked against the points file:
    the same space, the same drawables, the same points, in the same order. A sidecar from another
    capture is exit 2."""
    doc = read_json(path, "coverage sidecar")
    if not isinstance(doc, dict) or doc.get("$schema") != COVERAGE_V1:
        raise ProbeError("coverage sidecar %s is not schema %s" % (path, COVERAGE_V1))
    space = doc.get("space")
    if not isinstance(space, dict):
        raise ProbeError("coverage sidecar %s has no `space`" % path)
    measured_space = (space.get("width"), space.get("height"))
    declared = spec.get("space") or {}
    declared_space = (declared.get("width", DEFAULT_SPACE[0]), declared.get("height", DEFAULT_SPACE[1]))
    if measured_space != declared_space or measured_space != (raster.width, raster.height):
        raise ProbeError("coverage sidecar %s was measured on a %rx%r frame; the points file declares %rx%r "
                         "and the capture is %dx%d — they belong to different captures; re-capture"
                         % (path, measured_space[0], measured_space[1], declared_space[0], declared_space[1],
                            raster.width, raster.height))
    measured = {}
    labels = {}
    for m in _array(doc, "drawables", "coverage sidecar"):
        if not isinstance(m, dict):
            raise ProbeError("coverage sidecar: a drawable entry is not an object: %r" % (m,))
        did = m.get("id")
        if did not in ids:
            raise ProbeError("coverage sidecar %s measures drawable %r, which the points file does not "
                             "declare — the sidecar belongs to another capture; re-capture" % (path, did))
        if did in measured:
            raise ProbeError("coverage sidecar measures drawable %r twice" % did)
        _count(m.get("visible"), "coverage sidecar: %r `visible`" % did)
        if "label" in m:
            label = m.get("label")
            if isinstance(label, bool) or not isinstance(label, int) or not 1 <= label <= 0xFFFFFF:
                raise ProbeError("coverage sidecar: drawable %r has mask label %r (1..16777215)" % (did, label))
            if label in labels:
                raise ProbeError("coverage sidecar: mask label %d is used by both %r and %r"
                                 % (label, labels[label], did))
            labels[label] = did
            unshared = _count(m.get("unshared"), "coverage sidecar: %r `unshared`" % did)
            mapped = _count(m.get("mapped"), "coverage sidecar: %r `mapped`" % did)
            colour = _count(m.get("colourPixels"), "coverage sidecar: %r `colourPixels`" % did)
            if not colour <= mapped <= unshared <= m["visible"]:
                raise ProbeError("coverage sidecar: drawable %r must have colourPixels <= mapped <= unshared "
                                 "<= visible, got %d, %d, %d, %d" % (did, colour, mapped, unshared, m["visible"]))
            if m.get("texelSource") not in TEXEL_SOURCES:
                raise ProbeError("coverage sidecar: drawable %r has texelSource %r (%s)"
                                 % (did, m.get("texelSource"), " | ".join(TEXEL_SOURCES)))
            lab = m.get("expectLab")
            if lab is not None and (not isinstance(lab, list) or len(lab) != 3
                                    or any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in lab)):
                raise ProbeError("coverage sidecar: drawable %r has a malformed `expectLab`" % did)
        measured[did] = m
    missing = [did for did in ids if did not in measured]
    if missing:
        raise ProbeError("coverage sidecar %s does not measure %s — it belongs to another capture; "
                         "re-capture" % (path, ", ".join(missing)))
    measured_points = _array(doc, "points", "coverage sidecar")
    if len(measured_points) != len(points):
        raise ProbeError("coverage sidecar %s measures %d point(s); the points file declares %d — "
                         "re-capture" % (path, len(measured_points), len(points)))
    for point, m in zip(points, measured_points):
        if not isinstance(m, dict) or m.get("label") != point.get("label"):
            raise ProbeError("coverage sidecar point %r does not match points-file point %r — re-capture"
                             % (m.get("label") if isinstance(m, dict) else m, point.get("label")))
        if "x" in m and (m.get("x"), m.get("y")) != (point.get("x"), point.get("y")):
            raise ProbeError("coverage sidecar measured point %r at (%r, %r); the points file reads it at "
                             "(%r, %r) — re-capture" % (point.get("label"), m.get("x"), m.get("y"),
                                                        point.get("x"), point.get("y")))
        hits = m.get("hits", [])
        if not isinstance(hits, list) or any(not isinstance(h, str) for h in hits):
            raise ProbeError("coverage sidecar point %r has a malformed `hits`" % point.get("label"))
        unknown = [h for h in hits if h not in ids]
        if unknown:
            raise ProbeError("coverage sidecar point %r hits unknown drawable(s) %s — it belongs to another "
                             "capture; re-capture" % (point.get("label"), ", ".join(unknown)))
    return measured, measured_points


def mask_pixels(path, raster, wanted):
    """Pixel indices per wanted 24-bit label in the RGB mask."""
    if not os.path.isfile(path):
        raise ProbeError("the points file declares art-probed drawable(s) but the mask is missing: %s "
                         "(pass --mask)" % path)
    mask = load_raster(path)
    if (mask.width, mask.height) != (raster.width, raster.height):
        raise ProbeError("mask %s is %dx%d; the capture is %dx%d"
                         % (path, mask.width, mask.height, raster.width, raster.height))
    data = mask.data
    found = {}
    for index in range(mask.width * mask.height):
        j = index * 3
        label = (data[j] << 16) | (data[j + 1] << 8) | data[j + 2]
        if label and label in wanted:
            found.setdefault(label, []).append(index)
    return found


def settle_coverage(raster, spec, capture_path, mask_path, coverage_path, point_failures, verbose):
    """Art probes, presence probes, targets, the coverage verdict and the two lints. Returns the exit."""
    drawables, exemptions, ids, exempt = coverage_blocks(spec, "points file")
    art = spec.get("art") or {}
    tol = float(art.get("tolerance", DEFAULT_ART_TOLERANCE))
    min_pixels = int(art.get("minPixels", DEFAULT_MIN_PIXELS))
    points = spec.get("points") or []

    failures = point_failures
    warnings = 0
    for e in exemptions:
        if not e["drawables"]:
            warnings += 1
            print("WARN | unused exemption: the %s exemption of %s matched no drawable in this frame "
                  "(\"%s\") — it exempts nothing; remove it or point it at the drawable it was meant for "
                  "(exit unchanged)" % (e.get("scope", "drawable"), e.get("path"), str(e["reason"]).strip()))

    for point in points:
        target = point.get("target")
        if target and target not in ids:
            raise ProbeError("point %r targets unknown drawable %r" % (point.get("label"), target))

    measured, measured_points = {}, [{} for _ in points]
    if drawables:
        measured, measured_points = load_coverage(
            coverage_path or default_sidecar(capture_path, ".coverage.json"), ids, points, spec, raster)

    art_ids = [d["id"] for d in drawables if d["kind"] == "art" and d["id"] not in exempt]
    for did in art_ids:
        if "label" not in measured[did]:
            raise ProbeError("coverage sidecar gives art drawable %r no mask label — re-capture" % did)
    colour_pixels = {}
    if art_ids:
        wanted = dict((measured[did]["label"], did) for did in art_ids)
        found = mask_pixels(mask_path or default_mask_path(capture_path), raster, wanted)
        for label, did in wanted.items():
            colour_pixels[did] = found.get(label, [])
            if len(colour_pixels[did]) != measured[did]["colourPixels"]:
                raise ProbeError("mask and coverage sidecar disagree on %r: %d labelled pixels, %d measured "
                                 "— they belong to different captures; re-capture"
                                 % (did, len(colour_pixels[did]), measured[did]["colourPixels"]))

    # Which drawables each point probe really reads. A targeted probe must land on its target; a
    # target-less one is credited to the smallest non-exempt drawable visible at its centre (`hits`),
    # whatever the generator guessed from bounds alone.
    credited = {}
    reads = [None] * len(points)  # the drawable each point is attributed to, for the redundancy lint
    for index, point in enumerate(points):
        target = point.get("target")
        label = point.get("label", "?")
        m = measured_points[index]
        hits = m.get("hits", [])
        if target and point.get("attributed", "target") == "target":
            reads[index] = target
            route = ids[target].get("renderPath", "?")
            if target in exempt or int(measured.get(target, {}).get("visible", 1)) <= 0:
                continue  # the drawable's own line says why; one cause, one line
            if m.get("onTarget") is True or (m.get("onTarget") is None and target in hits):
                credited.setdefault(target, []).append(label)
                continue
            failures += 1
            print("FAIL | probe | %-52s | probe misses its target %s: its centre (%s, %s) is not on one of "
                  "the target's visible pixels (it reads %s) — aim the probe at the drawable, or retarget "
                  "it [%s]" % (label, target, point.get("x"), point.get("y"),
                               ", ".join(hits) if hits else "only the ground", route))
            continue
        if not drawables:
            continue
        owner = attribute(point.get("x"), point.get("y"), drawables, exempt, set(hits))
        if owner is None:
            if verbose and target:
                warn("not credited: %s is not visible at the centre of point probe %s" % (target, label))
            continue
        reads[index] = owner["id"]
        credited.setdefault(owner["id"], []).append(label)
        if verbose and owner["id"] != target:
            warn("point probe %s is credited to %s, the smallest drawable visible at its centre (the "
                 "generator guessed %s from bounds)" % (label, owner["id"], target or "nothing"))

    uncovered = 0
    defects = 0
    counts = {"art": 0, "presence": 0}
    lab_cache = {}
    data = raster.data
    for d in drawables:
        did = d["id"]
        route = d.get("renderPath", "?")
        kind = d["kind"]
        if did in exempt:
            print("EXEMPT | %-50s | %s [%s]" % (did, exempt[did], route))
            continue
        visible = int(measured[did]["visible"])
        probes = credited.get(did, [])
        if visible <= 0:
            behind = [p.get("label", "?") for p in points if p.get("target") == did]
            print("FAIL | cover | %-52s | never reaches the frame: 0 visible px (fully occluded, culled, "
                  "alpha 0, or drawn in its ground's colour)%s — exempt it with a reason if that is the "
                  "state this fixture shows [%s]"
                  % (did, (", so point probe(s) %s read what is behind it" % ", ".join(behind)) if behind
                     else "", route))
            failures += 1
            continue
        if kind == "art":
            indices = colour_pixels[did]
            count = len(indices)
            unshared = int(measured[did]["unshared"])
            mapped = int(measured[did]["mapped"])
            if mapped < min_pixels <= unshared:
                # Its own pixels, shared with nothing, that its own quad does not cover: the harness
                # mapped it wrong. Never an overlay, never a finding about the UI, never to be exempted.
                defects += 1
                print("ERROR | art  | %-51s | unmapped: %d unshared visible px but only %d map onto its own "
                      "quad (< %d) — a harness mapping defect (texture/UV mapping of this drawable), not an "
                      "overlay and not a UI fault; report it, never exempt it [%s]"
                      % (did, unshared, mapped, min_pixels, route))
                continue
            if count >= min_pixels:
                want = measured[did].get("expectLab")
                if want is None:
                    raise ProbeError("coverage sidecar gives %r %d colour pixels but no `expectLab`"
                                     % (did, count))
                counts["art"] += 1
                ls, as_, bs = [], [], []
                for i in indices:
                    j = i * 3
                    key = (data[j], data[j + 1], data[j + 2])
                    lab = lab_cache.get(key)
                    if lab is None:
                        lab = srgb_bytes_to_lab(key)
                        lab_cache[key] = lab
                    ls.append(lab[0])
                    as_.append(lab[1])
                    bs.append(lab[2])
                got = (_median(ls), _median(as_), _median(bs))
                de = delta_e76(got, want)
                ok = de <= tol
                failures += 0 if ok else 1
                via = measured[did].get("texelSource")
                print("%s | art   | %-52s | median Lab (%.1f, %.1f, %.1f) want (%.1f, %.1f, %.1f) | dE76 "
                      "%6.2f (tol %5.2f) | %d px [%s]%s"
                      % ("PASS" if ok else "FAIL", did, got[0], got[1], got[2], want[0], want[1], want[2],
                         de, tol, count, route,
                         " | texels via the import (no source PNG/JPG): an import-flag fault is invisible "
                         "here" if via == "import" else ""))
                continue
            if probes:
                if verbose:
                    warn("covered: %s is colour-unmeasurable (%d colour px) and covered by point probe(s) %s"
                         % (did, count, ", ".join(probes)))
                continue
            print("FAIL | art   | %-52s | colour-unmeasurable: %d visible px, %d unshared, only %d "
                  "colour-measurable (< %d) — every other pixel is shared with an overlapping drawable (a "
                  "translucent dim, a soft shadow) or carries no alpha; cover it with a point probe whose "
                  "Target names it, or ExemptHierarchy(<the overlaid subtree>, \"<reason>\") [%s]"
                  % (did, visible, unshared, count, min_pixels, route))
            failures += 1
            continue
        if kind == "text":
            if visible >= min_pixels:
                counts["presence"] += 1
                print("PASS | text  | %-52s | %d visible px (>= %d) [%s]" % (did, visible, min_pixels, route))
                continue
            if probes:
                continue
            print("FAIL | text  | %-52s | never reaches the frame: %d visible px (< %d) — no font, occluded, "
                  "alpha 0, or drawn in its ground's colour [%s]" % (did, visible, min_pixels, route))
            failures += 1
            continue
        if probes:
            if verbose:
                warn("covered: %s by point probe(s) %s" % (did, ", ".join(probes)))
            continue
        note = d.get("note")
        print("FAIL | cover | %-52s | UNCOVERED drawable on render path %s%s — add a point probe "
              "with Target, or context.Exempt(drawable, \"<reason>\")"
              % (did, route, (" (%s)" % note) if note else ""))
        uncovered += 1
        failures += 1

    warnings += redundancy_warnings(points, ids, reads)

    verdict = "ERROR" if defects else "DRIFT" if failures else "Ok"
    print("[%s] %s capture=%s points=%d art=%d presence=%d drawables=%d exempt=%d uncovered=%d "
          "failed=%d defects=%d warnings=%d"
          % (TOOL, verdict, capture_path, len(points), counts["art"], counts["presence"], len(drawables),
             len(exempt), uncovered, failures, defects, warnings))
    if defects:
        return EXIT_ERROR  # a harness defect outranks a verdict: the numbers behind it are wrong
    return EXIT_DRIFT if failures else EXIT_OK


def redundancy_warnings(points, ids, reads=None):
    """Two colour-purpose probes on one token (or one hex, with no token) and one render path prove one
    thing twice: WARN only. `reads` is the drawable each point was attributed to at the settle."""
    groups = {}
    order = []
    for index, point in enumerate(points):
        if point.get("purpose", "colour") != "colour":
            continue
        target = reads[index] if reads is not None else point.get("target")
        route = ids[target].get("renderPath", "?") if target in ids else \
            "(no drawable - the camera's clear colour)"
        colour = point.get("token") or str(point.get("expect", "")).upper()
        key = (colour, route)
        if key not in groups:
            groups[key] = []
            order.append(key)
        groups[key].append(point)
    count = 0
    for key in order:
        group = groups[key]
        if len(group) < 2:
            continue
        count += 1
        expect = str(group[0].get("expect", "")).upper()
        shown = key[0] if key[0] == expect else "%s [%s]" % (expect, key[0])
        print("WARN | redundant point probes: %d probes read %s on render path %s: %s — they prove "
              "one thing %d times; keep one colour probe and tag the rest purpose=presence (a lint tag "
              "only: each still reads and checks its colour) (exit unchanged)"
              % (len(group), shown, key[1], ", ".join(str(p.get("label", "?")) for p in group), len(group)))
    return count


# --- the generator ----------------------------------------------------------------------------
#
# A SKU's look lives on its prefabs and in its `LookLibrary` asset (a literal `#RRGGBB` read off the
# drawing Graphic settles a probe with no source file at all — see CaptureProbePoint.FromGraphic), and
# the field assertions already know each element's rect. So a sample point should be DERIVED from
# (rect, colour), never typed: type a coordinate and the probe file silently rots the first time the
# look moves. `tokenSource` below is optional, for a SKU that still keeps a constants file to derive
# symbolic names from; most probes just carry a literal hex expectation instead. The layout schema
# below is that derivation, written down.


_TOKEN_RE = re.compile(
    r"public\s+const\s+(?:int|float|double|string)\s+(\w+)\s*=\s*([^;]+);")


def load_design_tokens(path):
    if not os.path.isfile(path):
        raise ProbeError("tokenSource not found: %s" % path)
    with open(path, "r") as fh:
        source = fh.read()
    raw = {}
    for name, value in _TOKEN_RE.findall(source):
        raw[name] = value.strip()

    resolved = {}

    def resolve(name, seen):
        if name in resolved:
            return resolved[name]
        if name in seen:
            raise ProbeError("design token %s is defined circularly" % name)
        seen.add(name)
        value = raw[name]
        if value.startswith('"'):
            out = value.strip('"')
        elif re.match(r"^-?\d+(\.\d+)?[fdFD]?$", value):
            out = float(value.rstrip("fdFD")) if ("." in value) else int(value)
        elif value in raw:
            out = resolve(value, seen)
        else:
            raise ProbeError("cannot resolve design token %s = %s" % (name, value))
        resolved[name] = out
        return out

    for name in list(raw):
        resolve(name, set())
    return resolved


_ALLOWED_BINOPS = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow)


def evaluate(expression, symbols):
    """Arithmetic over design tokens. Deliberately not `eval`: names come from the token table
    and nothing else, and no call, attribute or subscript is reachable."""
    if isinstance(expression, (int, float)):
        return expression
    try:
        tree = ast.parse(str(expression), mode="eval")
    except SyntaxError as exc:
        raise ProbeError("cannot parse expression %r (%s)" % (expression, exc))

    def walk(node):
        if isinstance(node, ast.Expression):
            return walk(node.body)
        if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
            return node.value
        if isinstance(node, ast.Name):
            if node.id not in symbols:
                raise ProbeError("unknown design token %r in expression %r"
                                 % (node.id, expression))
            value = symbols[node.id]
            if not isinstance(value, (int, float)):
                raise ProbeError("design token %s is not numeric (%r)" % (node.id, value))
            return value
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
            value = walk(node.operand)
            return value if isinstance(node.op, ast.UAdd) else -value
        if isinstance(node, ast.BinOp) and isinstance(node.op, _ALLOWED_BINOPS):
            left, right = walk(node.left), walk(node.right)
            op = node.op
            if isinstance(op, ast.Add):
                return left + right
            if isinstance(op, ast.Sub):
                return left - right
            if isinstance(op, ast.Mult):
                return left * right
            if isinstance(op, ast.Div):
                return left / right
            if isinstance(op, ast.FloorDiv):
                return left // right
            if isinstance(op, ast.Mod):
                return left % right
            return left ** right
        raise ProbeError("expression %r uses a construct this evaluator refuses" % expression)

    return walk(tree)


def resolve_rects(layout, symbols):
    declared = layout.get("rects") or {}
    if not isinstance(declared, dict):
        raise ProbeError("layout `rects` must be an object")
    rects = {}

    def build(name, seen):
        if name in rects:
            return rects[name]
        if name in seen:
            raise ProbeError("rect %s is defined circularly" % name)
        seen.add(name)
        spec = declared.get(name)
        if spec is None:
            raise ProbeError("unknown rect %r" % name)
        if isinstance(spec, list):
            if len(spec) != 4:
                raise ProbeError("rect %s as a list must be [x, y, w, h]" % name)
            rect = [evaluate(v, symbols) for v in spec]
        elif isinstance(spec, dict):
            if "from" in spec:
                base = list(build(spec["from"], seen))
            else:
                base = [0.0, 0.0, 0.0, 0.0]
            for key, slot in (("x", 0), ("y", 1), ("w", 2), ("h", 3)):
                if key in spec:
                    base[slot] = evaluate(spec[key], symbols)
            if "size" in spec:
                base[2] = evaluate(spec["size"][0], symbols)
                base[3] = evaluate(spec["size"][1], symbols)
            if "offset" in spec:
                base[0] += evaluate(spec["offset"][0], symbols)
                base[1] += evaluate(spec["offset"][1], symbols)
            if "inset" in spec:
                pad = evaluate(spec["inset"], symbols)
                base = [base[0] + pad, base[1] + pad, base[2] - 2 * pad, base[3] - 2 * pad]
            rect = base
        else:
            raise ProbeError("rect %s must be a list or an object" % name)
        if rect[2] <= 0 or rect[3] <= 0:
            raise ProbeError("rect %s resolves to a non-positive extent %r" % (name, rect))
        rects[name] = rect
        return rect

    for name in declared:
        if name.startswith("_"):
            continue
        build(name, set())
    return rects


def generate_points(layout_path):
    layout = read_json(layout_path, "layout")
    symbols = {}
    token_source = layout.get("tokenSource")
    if token_source:
        if not os.path.isabs(token_source):
            token_source = os.path.join(repo_root(), token_source)
        symbols.update(load_design_tokens(token_source))
    for name, value in (layout.get("consts") or {}).items():
        if name.startswith("_"):  # `_note` keys are prose for the reader, not symbols
            continue
        symbols[name] = evaluate(value, symbols) if isinstance(value, str) else value

    space = layout.get("space") or {}
    out_space = {
        "width": int(evaluate(space.get("width", DEFAULT_SPACE[0]), symbols)),
        "height": int(evaluate(space.get("height", DEFAULT_SPACE[1]), symbols)),
        "origin": space.get("origin", "top-left"),
    }

    rects = resolve_rects(layout, symbols)
    v2 = is_v2(layout)
    probes = layout.get("probes")
    if not isinstance(probes, list) or (not probes and not v2):
        raise ProbeError("layout declares no `probes` array")
    if v2:
        drawables, exemptions, ids, exempt = coverage_blocks(layout, "layout")

    points = []
    for index, probe in enumerate(probes):
        label = probe.get("label") or "probe %d" % (index + 1)
        rect_name = probe.get("rect")
        if rect_name not in rects:
            raise ProbeError("probe %r names unknown rect %r" % (label, rect_name))
        rect = list(rects[rect_name])
        if "inset" in probe:
            pad = evaluate(probe["inset"], symbols)
            rect = [rect[0] + pad, rect[1] + pad, rect[2] - 2 * pad, rect[3] - 2 * pad]
        anchor = probe.get("at", "center")
        if anchor not in _ANCHORS:
            raise ProbeError("probe %r uses unknown anchor %r (known: %s)"
                             % (label, anchor, ", ".join(sorted(_ANCHORS))))
        fx, fy = _ANCHORS[anchor]
        x = rect[0] + fx * (rect[2] - 1)
        y = rect[1] + fy * (rect[3] - 1)
        if "nudge" in probe:
            x += evaluate(probe["nudge"][0], symbols)
            y += evaluate(probe["nudge"][1], symbols)

        expect = probe.get("expect")
        if expect is None:
            raise ProbeError("probe %r declares no `expect`" % label)
        token = None
        if not str(expect).startswith("#"):
            if expect not in symbols:
                raise ProbeError("probe %r expects unknown symbol %r (no literal #RRGGBB and no "
                                  "tokenSource/consts entry by that name)" % (label, expect))
            # Generic: whatever file tokenSource named (any SKU's own constants file), not a fixed
            # "DesignTokens" class — most SKUs carry no such file at all and expect a literal hex instead.
            source_name = os.path.splitext(os.path.basename(token_source))[0] if token_source else "consts"
            token = "%s.%s" % (source_name, expect)
            expect = symbols[expect]

        point = {
            "label": label,
            "x": int(round(x)),
            "y": int(round(y)),
            "expect": hex_of(parse_hex(expect)),
            "from": "rect %s [%g %g %g %g] at %s"
                    % (rect_name, rect[0], rect[1], rect[2], rect[3], anchor),
        }
        if token:
            point["token"] = token
        if "tolerance" in probe:
            point["tolerance"] = probe["tolerance"]
        if "window" in probe:
            point["window"] = probe["window"]
        if v2:
            purpose = probe.get("purpose", "colour")
            if purpose not in ("colour", "presence"):
                raise ProbeError("probe %r has purpose %r (colour | presence)" % (label, purpose))
            point["purpose"] = purpose
            target = probe.get("target")
            if target:
                if target not in ids:
                    raise ProbeError("probe %r targets unknown drawable %r" % (label, target))
                point["target"] = target
                point["attributed"] = "target"
            else:
                owner = attribute(point["x"], point["y"], drawables, exempt)
                if owner is not None:
                    point["target"] = owner["id"]
                    point["attributed"] = "centre"
                else:
                    point["attributed"] = "none"
        points.append(point)

    if v2:
        return {
            "$schema": POINTS_V2,
            "generated": "machine-generated by Tools/pf/pixel-probe.py --generate %s — "
                         "edit the surface, never this file"
                         % os.path.relpath(layout_path, repo_root()).replace(os.sep, "/"),
            "surface": layout.get("surface", "unnamed"),
            "space": out_space,
            "variance": layout.get("variance", {"minLuma": DEFAULT_MIN_VARIANCE}),
            "defaults": layout.get("defaults", {"tolerance": DEFAULT_TOLERANCE,
                                                "window": DEFAULT_WINDOW}),
            "art": layout.get("art", {"tolerance": DEFAULT_ART_TOLERANCE,
                                      "minPixels": DEFAULT_MIN_PIXELS}),
            "points": points,
            "drawables": drawables,
            "exemptions": exemptions,
        }

    return {
        "$schema": "pixel-probe/v1",
        "generated": "machine-generated by Tools/pf/pixel-probe.py --generate %s — "
                     "edit the layout, never this file"
                     % os.path.relpath(layout_path, repo_root()),
        "surface": layout.get("surface", "unnamed"),
        "space": out_space,
        "variance": layout.get("variance", {"minLuma": DEFAULT_MIN_VARIANCE}),
        "defaults": layout.get("defaults", {"tolerance": DEFAULT_TOLERANCE,
                                            "window": DEFAULT_WINDOW}),
        "points": points,
    }


def repo_root():
    return os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))


# --- entry point ------------------------------------------------------------------------------


def main(argv):
    parser = argparse.ArgumentParser(
        add_help=True,
        description="Settle a capture's floor deterministically — no model, no quota. "
                    "Exit 0 Ok, 1 Drift, 2 Error. See the header of this file for the full "
                    "contract and for why the tolerance is a CIE76 dE.")
    parser.add_argument("--capture", help="the PNG to read")
    parser.add_argument("--points", help="sample-point declaration (schema pixel-probe/v1 or v2)")
    parser.add_argument("--variance-only", dest="variance_only", metavar="PNG",
                        help="print the luma variance and settle ONLY the broken-capture check")
    parser.add_argument("--min-variance", type=float, default=None,
                        help="flat-capture threshold (default: the points file, else %.1f)"
                             % DEFAULT_MIN_VARIANCE)
    parser.add_argument("--window", type=int, default=None,
                        help="override every probe's sample-box size, in design units")
    parser.add_argument("--generate", metavar="LAYOUT",
                        help="machine-generate a points file from a layout declaration "
                             "(schema pixel-probe-layout/v1 or v2)")
    parser.add_argument("--out", help="where --generate writes (default: stdout)")
    parser.add_argument("--mask", help="the coverage label mask (default: <capture stem>.mask.png)")
    parser.add_argument("--coverage",
                        help="the coverage sidecar (default: <capture stem>.coverage.json)")
    parser.add_argument("--verbose", action="store_true",
                        help="also report the design->capture scale and each point's provenance")
    args = parser.parse_args(argv)

    if args.generate:
        spec = generate_points(args.generate)
        text = json.dumps(spec, indent=2) + "\n"
        if args.out:
            with open(args.out, "w") as fh:
                fh.write(text)
            warn("wrote %d points to %s" % (len(spec["points"]), args.out))
            if spec.get("$schema") == POINTS_V2:
                warn("coverage: %d drawable(s), %d exemption(s)"
                     % (len(spec["drawables"]), len(spec["exemptions"])))
        else:
            sys.stdout.write(text)
        return EXIT_OK

    if args.variance_only:
        raster = load_raster(args.variance_only)
        minimum = args.min_variance if args.min_variance is not None else DEFAULT_MIN_VARIANCE
        variance, flat = check_variance(raster, args.variance_only, minimum)
        print("%.4f" % variance)
        return EXIT_DRIFT if flat else EXIT_OK

    if not args.capture:
        raise ProbeError("give --capture, or --variance-only, or --generate")
    if not args.points:
        raise ProbeError("give --points <json> (or --variance-only for the flat-capture check)")

    spec = read_json(args.points, "points file")
    if not isinstance(spec, dict):
        raise ProbeError("points file is not a JSON object: %s" % args.points)
    raster = load_raster(args.capture)

    minimum = args.min_variance
    if minimum is None:
        minimum = float((spec.get("variance") or {}).get("minLuma", DEFAULT_MIN_VARIANCE))
    variance, flat = check_variance(raster, args.capture, minimum)
    if flat:
        return EXIT_ERROR  # a broken capture is an ERROR, never a colour DRIFT
    if args.verbose:
        warn("luma variance %.4f (>= %.4f) — capture carries real content" % (variance, minimum))

    # Only now, with the flat check behind us, is the v2 declaration validated: a broken capture
    # outranks every other finding, including a malformed coverage block.
    if not is_v2(spec):
        return run_probes(raster, spec, args.capture, args.window, args.verbose)
    coverage_blocks(spec, "points file")  # a blank exemption is exit 2 before any probe is read
    failures = run_probes(raster, spec, args.capture, args.window, args.verbose)
    return settle_coverage(raster, spec, args.capture, args.mask, args.coverage, failures, args.verbose)


if __name__ == "__main__":
    try:
        sys.exit(main(sys.argv[1:]))
    except ProbeError as error:
        sys.stderr.write("[%s] ERROR: %s\n" % (TOOL, error))
        sys.exit(EXIT_ERROR)
    except KeyboardInterrupt:
        sys.exit(EXIT_ERROR)
    except Exception as error:  # a malformed entry must never read as Drift
        sys.stderr.write("[%s] ERROR: unexpected %s: %s\n" % (TOOL, type(error).__name__, error))
        sys.exit(EXIT_ERROR)
